// Address→Keccak(address.Bytes) used as trie key (20 bytes → 32-byte keccak hash)
public Account? Get(Address address, Hash256? rootHash = null)
{
    ReadOnlySpan<byte> bytes = Get(KeccakCache.Compute(address.Bytes).BytesAsSpan, rootHash);
    return bytes.IsEmpty ? null : _decoder.Decode(bytes);
}

// CALLEE: src/Nethermind/Nethermind.State/PersistentStorageProvider.cs:EnsureStorageTree (lines 515-534)
public void EnsureStorageTree()
{
    if (StorageTree is not null) return;
    // _address is the Address object stored in PerContractState constructor
    Account? acc = _provider._stateProvider.GetAccount(_address);
    Hash256 storageRoot = acc?.StorageRoot ?? Keccak.EmptyTreeHash;
    StorageTree = _provider._storageTreeFactory.Create(_address,
        _provider._trieStore.GetTrieStore(_address),
        storageRoot,
        _provider.StateRoot,
        _provider._logManager);
}

